const API_TOKEN = '1985d3b7ffcc266add8f005be68caf8ff8ec605f';
const BASE = 'https://api.pipedrive.com/v1';
const DB = 'https://n8n.rnd.webpromo.tools/webhook/pipedrive-db';
const body = $input.first().json.body || $input.first().json;
const dateFrom = body.dateFrom;
const dateTo = body.dateTo;

async function api(method, path, payload) {
  const opts = {method, url: BASE + path + (path.includes('?') ? '&' : '?') + 'api_token=' + API_TOKEN};
  if (payload) {opts.body = payload; opts.headers = {'Content-Type':'application/json'};}
  return await this.helpers.httpRequest(opts);
}

async function db(sql) {
  return await this.helpers.httpRequest({method:'POST', url:DB, body:{query:sql}, headers:{'Content-Type':'application/json'}});
}

function esc(s) { if(!s) return ''; return String(s).replace(/\\/g,'\\\\').replace(/'/g,"''").replace(/\n/g,' ').replace(/\r/g,''); }

// Fetch deals from Pipedrive
let conditions = [];
if (dateFrom) conditions.push({field_id:12465,operator:'>=',value:dateFrom});
if (dateTo) conditions.push({field_id:12465,operator:'<=',value:dateTo});
let filterId = null;
let allDeals = [];

try {
  if (conditions.length) {
    const fp = {name:'sync_'+Date.now(),type:'deals',conditions:{glue:'and',conditions:[{glue:'and',conditions:conditions.map(c=>({object:'deal',field_id:c.field_id,operator:c.operator,value:c.value,extra_value:null}))}]}};
    const fRes = await api.call(this,'POST','/filters',fp);
    filterId = fRes.data.id;
  }
  let start=0, hasMore=true, pages=0;
  while(hasMore && pages<50){
    let url='/deals?limit=500&start='+start;
    if(filterId) url+='&filter_id='+filterId;
    const r = await api.call(this,'GET',url);
    if(r.data) allDeals = allDeals.concat(r.data);
    const p = r.additional_data && r.additional_data.pagination;
    hasMore = p && p.more_items_in_collection;
    if(hasMore) start = p.next_start;
    pages++;
  }
} finally {
  if(filterId) try{await api.call(this,'DELETE','/filters/'+filterId);}catch(e){}
}

// Insert into Postgres in batches
let inserted = 0;
let errors = 0;
let errorMsgs = [];

for (const d of allDeals) {
  try {
    const ownerId = (d.user_id && typeof d.user_id==='object') ? d.user_id.id : (d.user_id||0);
    const ownerName = esc(d.user_id && typeof d.user_id==='object' ? (d.user_id.name||'') : '');
    const personName = esc(d.person_id && typeof d.person_id==='object' ? (d.person_id.name||'') : '');
    const orgName = esc(d.org_id && typeof d.org_id==='object' ? (d.org_id.name||'') : '');
    const title = esc(d.title || '');
    const lostReason = esc(d.lost_reason || '');

    const sql = `INSERT INTO pipedrive.deals(id,title,status,pipeline_id,stage_id,owner_id,owner_name,person_name,org_name,value,currency,label,add_time,update_time,won_time,lost_time,lost_reason,synced_at) VALUES(${d.id},'${title}','${d.status||'open'}',${d.pipeline_id?d.pipeline_id:'NULL'},${d.stage_id?d.stage_id:'NULL'},${ownerId?ownerId:'NULL'},'${ownerName}','${personName}','${orgName}',${d.value||0},'${d.currency||'UAH'}','${d.label||''}',${d.add_time?"'"+d.add_time+"'":'NULL'},${d.update_time?"'"+d.update_time+"'":'NULL'},${d.won_time?"'"+d.won_time+"'":'NULL'},${d.lost_time?"'"+d.lost_time+"'":'NULL'},'${lostReason}',NOW()) ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,status=EXCLUDED.status,pipeline_id=EXCLUDED.pipeline_id,stage_id=EXCLUDED.stage_id,owner_id=EXCLUDED.owner_id,owner_name=EXCLUDED.owner_name,person_name=EXCLUDED.person_name,org_name=EXCLUDED.org_name,value=EXCLUDED.value,label=EXCLUDED.label,add_time=EXCLUDED.add_time,update_time=EXCLUDED.update_time,won_time=EXCLUDED.won_time,lost_time=EXCLUDED.lost_time,lost_reason=EXCLUDED.lost_reason,synced_at=NOW()`;

    await db.call(this, sql);
    inserted++;
  } catch(e) {
    errors++;
    if(errors<=3) errorMsgs.push({id:d.id, title:d.title, error:e.message||String(e)});
  }
}

return [{json:{success:true, total:allDeals.length, inserted, errors, errorSamples:errorMsgs}}];
